1	import * as tvmjs from "@mlc-ai/web-runtime";
2	import * as xgr from "@mlc-ai/web-xgrammar";
3	import log from "loglevel";
4	import { Tokenizer } from "@mlc-ai/web-tokenizers";
5	import { ChatConfig, GenerationConfig, Role } from "./config";
6	import { getConversation, Conversation } from "./conversation";
7	import { LogitProcessor, LatencyBreakdown } from "./types";
8	import {
9	  getChunkedPrefillInputData,
10	  getImageDataFromURL,
11	  getRGBArrayFromImageData,
12	  getTokenTableFromTokenizer,
13	  getTopProbs,
14	} from "./support";
15	import {
16	  ChatCompletionFinishReason,
17	  ChatCompletionTokenLogprob,
18	  TopLogprob,
19	  ResponseFormat,
20	  ChatCompletionContentPartImage,
21	} from "./openai_api_protocols/index";
22	import {
23	  AttentionSinkSizeError,
24	  ContextWindowSizeExceededError,
25	  MinValueError,
26	  RangeError,
27	  WindowSizeConfigurationError,
28	  WindowSizeSpecificationError,
29	  MessageOrderError,
30	  TextCompletionExpectsKVEmptyError,
31	  CannotFindImageEmbedError,
32	} from "./error";
33	
34	type ImageURL = ChatCompletionContentPartImage.ImageURL;
35	
36	type KVStateKind = "kv_cache" | "rnn_state" | "hybrid" | "none";
37	type ComputeABIKind = "single" | "batch";
38	
39	type VMFunctionAvailability = {
40	  prefill: boolean;
41	  batch_prefill: boolean;
42	  decode: boolean;
43	  batch_decode: boolean;
44	  create_tir_paged_kv_cache: boolean;
45	  create_rnn_state: boolean;
46	};
47	
48	type VMFunctionRegistry = Record<string, tvmjs.PackedFunc | undefined>;
49	
50	type ResolvedModelABI = {
51	  kvStateKind: Exclude<KVStateKind, "none">;
52	  prefillABI: ComputeABIKind;
53	  decodeABI: ComputeABIKind;
54	  prefillFunctionName: "prefill" | "batch_prefill";
55	  decodeFunctionName: "decode" | "batch_decode";
56	  needsKVCache: boolean;
57	  needsRNNState: boolean;
58	};
59	
60	export class LLMChatPipeline {
61	  private config: ChatConfig;
62	  private tokenizer: Tokenizer;
63	
64	  // TVM functions
65	  private tvm: tvmjs.Instance;
66	  private device: tvmjs.DLDevice;
67	  private vm: tvmjs.VirtualMachine;
68	  private prefill: tvmjs.PackedFunc;
69	  private decoding: tvmjs.PackedFunc;
70	  private resolvedModelABI!: ResolvedModelABI;
71	  private kvStateKind: KVStateKind = "kv_cache";
72	  private image_embed: tvmjs.PackedFunc | undefined;
73	  private embed: tvmjs.PackedFunc;
74	  private fapplyBitmask: tvmjs.PackedFunc;
75	  private fapplyPenalty: tvmjs.PackedFunc;
76	  private fapplyLogitBias: tvmjs.PackedFunc;
77	  private fsoftmaxWithTemperature: tvmjs.PackedFunc;
78	  private fsampleWithTopP: tvmjs.PackedFunc;
79	  private fargsortProbs: tvmjs.PackedFunc;
80	
81	  // Functions related to PagedKVCache
82	  private fclearKVCaches: tvmjs.PackedFunc;
83	  private fKVCacheAddSequence: tvmjs.PackedFunc;
84	  private fKVCacheRemoveSequence: tvmjs.PackedFunc;
85	  private fKVCacheBeginForward: tvmjs.PackedFunc;
86	  private fKVCacheEndForward: tvmjs.PackedFunc;
87	  private fKVCacheEnableSlidingWindowForSeq: tvmjs.PackedFunc;
88	
89	  // parameter states
90	  private params: tvmjs.TVMObject;
91	  private kvCache?: tvmjs.TVMObject = undefined;
92	  private rnnState?: tvmjs.TVMObject = undefined;
93	  private prefillLogitPositions?: tvmjs.Tensor = undefined;
94	  private prefillLogitPositionHost = new Int32Array(1);
95	  private maxHistorySize = 1;
96	  private logitsOnCPU?: tvmjs.Tensor = undefined;
97	  private filledKVCacheLength = 0;
98	
99	  // meta data
100	  private bosTokenId = 1;
101	  private contextWindowSize = -1;
102	  private slidingWindowSize = -1;
103	  private attentionSinkSize = -1;
104	  private prefillChunkSize = -1;
105	  private resetStatsPerPrefill = true;
106	  private stopStr: string[];
107	  private stopTokens: Array<number>;
108	
109	  // states
110	  private outputMessage = "";
111	  private outputIds: Array<number> = [];
112	  private stopTriggered = false;
113	  private finishReason: ChatCompletionFinishReason | undefined = undefined;
114	  // frequency of appeared token ids till now (refresh after PrefillStep); token_id mapped to freq
115	  private appearedTokensFreq = new Map<number, number>();
116	  private imageDataCache = new Map<string, ImageData>();
117	  private conversation: Conversation;
118	  // The logprob information of all tokens for this current round (cleared upon each prefillStep)
119	  // Cleared & updated at the exact same spots as `outputMessage`. Only updated when
120	  // `genConfig.logprobs` is true. Each entry corresponds to a single autoregressive step.
121	  private tokenLogprobArray: Array<ChatCompletionTokenLogprob> = [];
122	
123	  // stats, reset at every `resetChat(keepstats=false)`
124	  private decodingTotalTime = 0;
125	  private decodingTotalTokens = 0;
126	  private prefillTotalTime = 0;
127	  private prefillTotalTokens = 0;
128	  // same stats as above, but reset at every `prefillStep()`
129	  private curRoundDecodingTotalTokens = 0;
130	  private curRoundPrefillTotalTokens = 0;
131	  private curRoundDecodingTotalTime = 0;
132	  private curRoundPrefillTotalTime = 0;
133	
134	  // additional stats, reset at every prefillStep()
135	  public curRoundLatencyBreakdown: LatencyBreakdown = {
136	    logitProcessorTime: [],
137	    logitBiasTime: [],
138	    penaltyTime: [],
139	    sampleTime: [],
140	    totalTime: [],
141	    grammarBitmaskTime: [],
142	  };
143	
144	  // LogitProcessor
145	  private logitProcessor?: LogitProcessor = undefined;
146	
147	  // Grammar-related
148	  // A grammar matcher for this current round if response_format is set. Reinitialized upon
149	  // each step regardless of whether the chat is multi-round or not.
150	  private grammarMatcher?: xgr.GrammarMatcher = undefined;
151	  // Cache key of the current response_format (schema / grammar / structural tag). If undefined,
152	  // grammarMatcher is simply using JSON mode. We use this field to determine whether we re-initiate
153	  // a GrammarMatcher or simply reset during each round (i.e. during prefillStep).
154	  private responseFormatCacheKey?: string = undefined;
155	  // A string list of tokens ordered by their token id, post-processed. Once initialized, will not
156	  // be reinitialized since `this.tokenizer` does not change throughout the lifetime of LLMChatPipeline.
157	  private xgTokenizerInfo?: xgr.TokenizerInfo = undefined;
158	  // Compiler for grammar. It is persistent since it specializes on xgTokenizerInfo.
159	  private grammarCompiler?: xgr.GrammarCompiler = undefined;
160	  // Size of the bitmask for grammar, determined by fullVocabSize
161	  private bitmaskSize: number;
162	  // `vocab_size` read from `config.json`. Can be different from the size of the tokenTable for some
163	  // models due to dummy padded tokens.
164	  private fullVocabSize: number;
165	  // Method to post process the token for grammar; either "byte_level" or default "byte_fallback".
166	  private token_postproc_method: string;
167	  // Whether to prepend space for grammar
168	  private prepend_space_in_encode: boolean;
169	  // stats for grammar-related overhead
170	  // Time to initialize grammar matcher in seconds
171	  private curRoundGrammarInitTotalTime = 0;
172	  // Total time of getting next bitmask and accepting token in seconds
173	  private curRoundGrammarPerTokenTotalTime = 0;
174	  // Instance variables for supporting sampling on WebGPU
175	  private sampleIndices: Int32Array;
176	  private sampleIndicesDevice: tvmjs.Tensor;
177	  private topPDevice: tvmjs.Tensor;
178	
179	  constructor(
180	    tvm: tvmjs.Instance,
181	    tokenizer: Tokenizer,
182	    config: ChatConfig,
183	    logitProcessor?: LogitProcessor,
184	  ) {
185	    // 0. Setting attributes
186	    this.tvm = tvm;
187	    this.tokenizer = tokenizer;
188	    this.config = config;
189	    this.logitProcessor = logitProcessor;
190	    this.fullVocabSize = this.config.vocab_size;
191	    this.bitmaskSize = Math.ceil(this.fullVocabSize / 32);
192	
193	    this.conversation = getConversation(
194	      config.conv_template,
195	      config.conv_config,
196	    );
197	    this.stopStr = this.conversation.getStopStr();
198	    this.stopTokens = this.conversation.getStopTokens();
199	    if (config.bos_token_id !== undefined) {
200	      this.bosTokenId = config.bos_token_id;
201	    }
202	    // Set token_post_proc_method, currently mlc-chat-config.json are unstable, hence various
203	    // fallback mechanisms
204	    if (config.tokenizer_info !== undefined) {
205	      this.token_postproc_method = config.tokenizer_info.token_postproc_method;
206	      this.prepend_space_in_encode =
207	        config.tokenizer_info.prepend_space_in_encode;
208	    } else if (config.token_table_postproc_method !== undefined) {
209	      this.token_postproc_method = config.token_table_postproc_method;
210	      this.prepend_space_in_encode = false;
211	    } else {
212	      log.warn(
213	        "Cannot find `tokenizer_info` or `token_table_postproc_method` in `mlc-chat-config.json`, " +
214	          "using default token_postproc_method `raw`.\n" +
215	          "This field is only used for json mode.",
216	      );
217	      this.token_postproc_method = "raw";
218	      this.prepend_space_in_encode = false;
219	    }
220	    log.info("token_postproc_method: ", this.token_postproc_method);
221	    log.info("prepend_space_in_encode: ", this.prepend_space_in_encode);
222	
223	    this.device = this.tvm.webgpu();
224	
225	    // 1. Create VM and read model metadata
226	    tvm.beginScope();
227	    this.vm = this.tvm.detachFromCurrentScope(
228	      this.tvm.createVirtualMachine(this.device),
229	    );
230	
231	    const vmFunctionRegistry = LLMChatPipeline.loadVMFunctionRegistry(this.vm, [
232	      "prefill",
233	      "batch_prefill",
234	      "decode",
235	      "batch_decode",
236	      "create_tir_paged_kv_cache",
237	      "create_rnn_state",
238	      "sample_with_top_p",
239	      "argsort_probs",
240	      "image_embed",
241	      "embed",
242	      "apply_bitmask_inplace",
243	      "apply_penalty_inplace",
244	      "apply_logit_bias_inplace",
245	      "softmax_with_temperature",
246	    ]);
247	
248	    const fgetMetadata = this.vm.getFunction("_metadata");
249	    const ret_value = fgetMetadata();
250	    const metadataStr = ret_value.toString();
251	    const metadata = JSON.parse(metadataStr);
252	    this.kvStateKind = this.parseKVStateKind(metadata.kv_state_kind);
253	
254	    const vmFunctionAvailability =
255	      LLMChatPipeline.getVMFunctionAvailability(vmFunctionRegistry);
256	    this.resolvedModelABI = LLMChatPipeline.resolveModelABI(
257	      this.kvStateKind,
258	      vmFunctionAvailability,
259	    );
260	    const stateKinds: string[] = [];
261	    if (this.resolvedModelABI.needsKVCache) {
262	      stateKinds.push("kv_cache");
263	    }
264	    if (this.resolvedModelABI.needsRNNState) {
265	      stateKinds.push("rnn_state");
266	    }
267	    log.info(
268	      "Resolved model ABI:",
269	      JSON.stringify({
270	        kv_state_kind: this.kvStateKind,
271	        prefill: this.resolvedModelABI.prefillFunctionName,
272	        decode: this.resolvedModelABI.decodeFunctionName,
273	        states: stateKinds,
274	      }),
275	    );
276	
277	    // 2. Bind VM functions according to the resolved ABI
278	    this.prefill = this.tvm.detachFromCurrentScope(
279	      LLMChatPipeline.getRequiredVMFunctionByName(
280	        this.resolvedModelABI.prefillFunctionName,
281	        vmFunctionRegistry,
282	      ),
283	    );
284	    this.decoding = this.tvm.detachFromCurrentScope(
285	      LLMChatPipeline.getRequiredVMFunctionByName(
286	        this.resolvedModelABI.decodeFunctionName,
287	        vmFunctionRegistry,
288	      ),
289	    );
290	    if (this.resolvedModelABI.prefillABI === "batch") {
291	      log.info("Using batch_prefill kernel.");
292	    }
293	    if (this.resolvedModelABI.decodeABI === "batch") {
294	      log.info("Using batch_decode kernel.");
295	    }
296	
297	    this.embed = this.tvm.detachFromCurrentScope(
298	      LLMChatPipeline.getRequiredVMFunctionByName("embed", vmFunctionRegistry),
299	    );
300	    this.fapplyBitmask = this.tvm.detachFromCurrentScope(
301	      LLMChatPipeline.getRequiredVMFunctionByName(
302	        "apply_bitmask_inplace",
303	        vmFunctionRegistry,
304	      ),
305	    );
306	    this.fapplyPenalty = this.tvm.detachFromCurrentScope(
307	      LLMChatPipeline.getRequiredVMFunctionByName(
308	        "apply_penalty_inplace",
309	        vmFunctionRegistry,
310	      ),
311	    );
312	    this.fapplyLogitBias = this.tvm.detachFromCurrentScope(
313	      LLMChatPipeline.getRequiredVMFunctionByName(
314	        "apply_logit_bias_inplace",
315	        vmFunctionRegistry,
316	      ),
317	    );
318	    this.fsoftmaxWithTemperature = this.tvm.detachFromCurrentScope(
319	      LLMChatPipeline.getRequiredVMFunctionByName(
320	        "softmax_with_temperature",
321	        vmFunctionRegistry,
322	      ),
323	    );
324	    this.fsampleWithTopP = this.tvm.detachFromCurrentScope(
325	      LLMChatPipeline.getRequiredVMFunctionByName(
326	        "sample_with_top_p",
327	        vmFunctionRegistry,
328	      ),
329	    );
330	    this.fargsortProbs = this.tvm.detachFromCurrentScope(
331	      LLMChatPipeline.getRequiredVMFunctionByName(
332	        "argsort_probs",
333	        vmFunctionRegistry,
334	      ),
335	    );
336	    const imageEmbed = vmFunctionRegistry.image_embed;
337	    if (imageEmbed !== undefined) {
338	      this.image_embed = this.tvm.detachFromCurrentScope(imageEmbed);
339	    } else {
340	      log.info("Cannot find function image_embed.");
341	    }
342	
343	    // 3. Load parameters by name
344	    const paramNames: string[] = [];
345	    metadata.params.forEach((param: any) => {
346	      paramNames.push(param.name);
347	    });
348	    this.params = this.tvm.detachFromCurrentScope(
349	      this.tvm.getParamsFromCacheByName(paramNames),
350	    );
351	
352	    // 4. Read in compilation configurations from metadata
353	    this.prefillChunkSize = metadata.prefill_chunk_size;
354	    log.info("Using prefillChunkSize: ", this.prefillChunkSize);
355	    if (this.prefillChunkSize <= 0) {
356	      throw new MinValueError("prefill_chunk_size", 0);
357	    }
358	
359	    // 5. Consolidate KVCache settings: context window, sliding window, attention sink
360	    this.slidingWindowSize = config.sliding_window_size;
361	    this.contextWindowSize = config.context_window_size;
362	    this.attentionSinkSize = config.attention_sink_size;
363	    if (this.contextWindowSize !== -1 && this.slidingWindowSize !== -1) {
364	      throw new WindowSizeConfigurationError(
365	        this.contextWindowSize,
366	        this.slidingWindowSize,
367	      );
368	    } else if (this.slidingWindowSize != -1) {
369	      // Use sliding window and attention sink
370	      log.info("Using slidingWindowSize: ", this.slidingWindowSize);
371	      if (this.attentionSinkSize >= 0) {
372	        log.info("Using attentionSinkSize: ", this.attentionSinkSize);
373	      } else {
374	        throw new AttentionSinkSizeError();
375	      }
376	    } else if (this.contextWindowSize != -1) {
377	      // Use default kv cache without sliding window
378	      log.info("Using contextWindowSize: ", this.contextWindowSize);
379	    } else {
380	      throw new WindowSizeSpecificationError();
381	    }
382	    if (
383	      config.max_history_size !== undefined &&
384	      config.max_history_size !== null
385	    ) {
386	      if (config.max_history_size <= 0) {
387	        throw new MinValueError("max_history_size", 0);
388	      }
389	      this.maxHistorySize = config.max_history_size;
390	    } else if (this.resolvedModelABI.needsRNNState) {
391	      // Hybrid/recurrent models can over-allocate RNN state if we use context window directly.
392	      // Keep browser default conservative unless user explicitly overrides max_history_size.
393	      log.info("max_history_size is not set. Using browser-safe default: 1");
394	    }
395	
396	    // 5. Create cache
397	    // Load cache functions and instantiate KVCache
398	    this.fclearKVCaches = this.tvm.detachFromCurrentScope(
399	      this.tvm.getGlobalFunc("vm.builtin.kv_state_clear"),
400	    );

