async reload(
  modelId: string | string[],
  chatOpts?: ChatOptions | ChatOptions[],
): Promise<void> {
  // 0. Unload all loaded models
  await this.unload();
  // 1. Convert inputs to arrays
  if (!Array.isArray(modelId)) {
    modelId = [modelId];
  }
  if (chatOpts !== undefined && !Array.isArray(chatOpts)) {
    chatOpts = [chatOpts];
  }
